#include <bits/stdc++.h>
using namespace std;

long long modh(long long a, long long M, int h, int mod) {
    long long r = a - ((M * (a & ((1LL << 31) - 1)) >> 31) + M * (a >> 31) >> (h - 31)) * mod;
    return r < mod ? r : r - mod;
}

long long pow_mod(long long a, long long n, long long mod) {
    long long ret = 1;
    for (int x = 63 - __builtin_clzll(n); x >= 0; x--) {
        ret = ret * ret % mod;
        if ((n << (63 - x)) < 0)
            ret = ret * a % mod;
    }
    return ret;
}

long long invl(long long a, long long mod) {
    long long b = mod, p = 1, q = 0;
    while (b > 0) {
        long long c = a / b, d = a;
        a = b; b = d % b;
        d = p; p = q; q = d - c * q;
    }
    return p < 0 ? p + mod : p;
}

vector<long long> nttmb(const vector<long long>& src, int n, bool inverse, int P, int g) {
    vector<long long> dst(src);
    int h = __builtin_ctz(n);
    long long K = 1LL << (64 - __builtin_clzll(P));
    int H = __builtin_ctzll(K) * 2;
    long long M = K * K / P;
    vector<int> wws(1 << (h - 1));
    long long dw = inverse ? pow_mod(g, P - 1 - (P - 1) / n, P) : pow_mod(g, (P - 1) / n, P);
    long long w = (1LL << 32) % P;
    for (int k = 0; k < (1 << (h - 1)); k++) {
        wws[k] = (int)w;
        w = (long long)modh(w * dw, M, H, P);
    }
    long long J = invl(P, 1LL << 32);
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < (1 << i); j++) {
            for (int k = 0, s = j << (h - i), t = s | (1 << (h - i - 1)); k < (1 << (h - i - 1)); k++, s++, t++) {
                long long u = (dst[s] - dst[t] + 2 * P) * wws[k] % P;
                dst[s] = (dst[s] + dst[t]) % P;
                long long Q = ((u << 32) * J) >> 32;
                dst[t] = ((u >> 32) - (Q * P >> 32) + P) % P;
            }
        }
        if (i < h - 1) {
            for (int k = 0; k < (1 << (h - i - 2)); k++) wws[k] = wws[k * 2];
        }
    }
    for (int i = 0; i < n; i++) {
        if (dst[i] >= P) dst[i] -= P;
    }
    for (int i = 0; i < n; i++) {
        int rev = __builtin_bitreverse(i) >> (32 - h);
        if (i < rev) {
            long long d = dst[i];
            dst[i] = dst[rev];
            dst[rev] = d;
        }
    }
    if (inverse) {
        long long in = invl(n, P);
        for (int i = 0; i < n; i++) dst[i] = modh(dst[i] * in, M, H, P);
    }
    return dst;
}

vector<long long> convoluteSimply(const vector<long long>& a, const vector<long long>& b, int P, int g) {
    int m = max(2, 1 << (32 - __builtin_clz(max((int)a.size(), (int)b.size()) - 1) + 2));
    vector<long long> fa = nttmb(a, m, false, P, g);
    vector<long long> fb;
    if (&a == &b) {
        fb = fa;
    } else {
        fb = nttmb(b, m, false, P, g);
    }
    for (int i = 0; i < m; i++) {
        fa[i] = fa[i] * fb[i] % P;
    }
    return nttmb(fa, m, true, P, g);
}

